/*
 * A375372  Expansion of 1/( (1 + x) * (1 - x^2*(1 + x)^2) ).
 * https://oeis.org/A375372
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  sign, easy
 * Formula:   a(n) = -a(n-1) + a(n-2) + 3*a(n-3) + 3*a(n-4) + a(n-5) Initial
 *            values: a(0)=1, a(1)=-1, a(2)=2, a(3)=0, a(4)=2, a(5)=2 The
 *            sequence is generated by this 5‑term linear recurrence
 * Range:     i8 n <= 13, i16 n <= 24, i32 n <= 41, i64 n <= 41, i128 n <= 41,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* seq_t and idx_t are supplied by the build. */

/* Static cache for memoisation. */
static seq_t *cache = NULL;   /* array of computed values */
static size_t cap   = 0;       /* current allocated size */

/* Ensure that values up to index n are computed and cached. */
static void ensure_cache(idx_t n)
{
    size_t needed = (size_t)n + 1;
    if (needed <= cap)                /* already available */
        return;

    /* Reallocate cache to the required size. */
    seq_t *tmp = (seq_t *)realloc(cache, needed * sizeof(seq_t));
    if (!tmp)                         /* allocation failed */
        abort();
    cache = tmp;

    /* Initialise the first six terms if they are still missing. */
    if (cap == 0) {
        cache[0] =  1;
        if (needed > 1) cache[1] = -1;
        if (needed > 2) cache[2] =  2;
        if (needed > 3) cache[3] =  0;
        if (needed > 4) cache[4] =  2;
        if (needed > 5) cache[5] =  2;
    } else {
        for (size_t i = cap; i <= (size_t)5 && i < needed; ++i) {
            if (i == 0) cache[0] =  1;
            else if (i == 1) cache[1] = -1;
            else if (i == 2) cache[2] =  2;
            else if (i == 3) cache[3] =  0;
            else if (i == 4) cache[4] =  2;
            else if (i == 5) cache[5] =  2;
        }
    }

    /* Compute remaining terms using the recurrence. */
    size_t start = (cap < 6) ? 6 : cap;
    for (size_t i = start; i < needed; ++i) {
        cache[i] = -cache[i-1] + cache[i-2]
                   + 3 * cache[i-3] + 3 * cache[i-4] + cache[i-5];
    }

    cap = needed;
}

/* Public routine requested by the problem statement. */
seq_t a(idx_t n)
{
    ensure_cache(n);
    return cache[(size_t)n];
}
